  .cat-grid .cat-card:last-child { grid-column: 1 / -1; flex-direction: row; align-items: center; }
  .hero-card-topic { display: none; }
  .cat-card:last-child .cat-meta { margin-top: 0; margin-left: auto; }
  .cat-ic { width: 56px; height: 56px; }
  .cat-ic .ic { width: 32px; height: 32px; }
  .cat-title { font-size: 17px; }
  .cat-card:last-child .cat-body .t-sm { display: none; }
  /* compact horizontal product cards */
  .product-grid-4, .product-grid-3 { grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .product-grid-4 > .pcard:nth-child(4) { display: grid; }
  .pcard { display: grid; grid-template-columns: 124px minmax(0, 1fr); }
  .pcard:hover { transform: none; }
  .pcard-media { padding: 12px 8px; display: grid; align-items: center; }
  .pcard-media .visual { aspect-ratio: 3 / 4; }
  .pcard-media .book { width: 72cqw; }
  .pcard-media .visual-bundle .book { width: 62cqw; transform: translateX(-12cqw); }
  .pcard-media .visual-bundle .device { width: 36cqw; right: 6cqw; bottom: 14cqw; }
  .pcard-media .visual-device .device { width: 62cqw; }
  .pcard-badges { top: 8px; left: 8px; }
  .pcard-badges .badge { height: 20px; font-size: 11px; padding: 0 6px; }
  .pcard-body { padding: 14px 14px 14px 12px; gap: 4px; }
  .pcard-title { font-size: 16px; }
  .pcard-desc { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; font-size: 13px; }
  .pcard-foot { padding-top: 8px; }
  .price { font-size: 18px; }
  .btn-cart { width: 48px; height: 44px; }
  .split .btn-row .t-sm { width: 100%; text-align: center; }
  .steps-4, .steps-5 { grid-template-columns: minmax(0, 1fr); row-gap: 0; }
  .step { display: grid; grid-template-columns: 48px minmax(0, 1fr); column-gap: 16px; padding-bottom: 28px; }
  .step .step-num { grid-row: 1 / 3; margin-bottom: 0; }
  .step::after, .steps-4 .step:nth-child(2)::after, .steps-5 .step:nth-child(3)::after { display: block; top: 56px; bottom: 4px; left: 23px; right: auto; width: 2px; height: auto; background: repeating-linear-gradient(180deg, var(--sky-light) 0 6px, transparent 6px 12px); }
  .step:last-child::after { display: none; }
  .step .t-h3 { font-size: 18px; }
  .review-grid { grid-template-columns: minmax(0, 1fr); }
  .review-grid > .review:nth-child(n+4) { display: none; }
  .review { padding: 20px; }
  .rating-big strong { font-size: 48px; }
  .cta-band { padding: 32px 20px; border-radius: var(--r-lg); }
  .cta-trust { flex-direction: column; }
  .footer { padding-top: 48px; }
  .footer-top { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 32px 20px; padding-bottom: 32px; }
  .footer-col:last-child { grid-column: 1 / -1; }
  .footer-trust { flex-direction: column; }
  /* page top & shop */
  .page-top { padding: 16px 0 28px; }
  .page-top-slim { padding-bottom: 0; }
  .breadcrumb ol { font-size: 13px; margin-bottom: 14px; }
  .page-head { flex-direction: column; align-items: flex-start; gap: 20px; }
  .page-head-usps { display: none; }
  .chip-row { flex-wrap: nowrap; overflow-x: auto; margin-inline: calc(-1 * var(--gutter)); padding-inline: var(--gutter); scrollbar-width: none; margin-top: 20px; }
  .chip-row::-webkit-scrollbar { display: none; }
  .shop-section { padding-top: 20px; }
  .toolbar { flex-wrap: wrap; gap: 10px; }
  .search { flex-basis: 100%; }
  .filters-open { flex: 1; height: 48px; }
  .sort { flex: 1.3; margin-left: 0; }
  .sort-label { display: none; }
  .sort .select, .sort select { width: 100%; }
  .guide-grid, .feature-grid { grid-template-columns: minmax(0, 1fr); }
  .guide-card, .feature-card { padding: 22px; }
  /* pdp */
  .pdp { padding-bottom: 48px; }
  .gallery-main { padding: 28px 12px 8px; border-radius: var(--r-lg); }
  .gallery-stage .book { width: 58cqw; }
  .thumbs { gap: 6px; }
  .thumb { padding: 8px 4px; }
  .thumb-art { width: 32px; height: 32px; }
  .thumb-cap { font-size: 11px; }
  .price-xl { font-size: 28px; }
  .buy-row { flex-wrap: wrap; }
  .buy-row .qty { width: 100%; grid-template-columns: 56px minmax(0, 1fr) 56px; }
  .buy-btn { flex-basis: 100%; }
  .upsell { grid-template-columns: 64px minmax(0, 1fr); }
  .upsell-price { grid-column: 2; flex-direction: row; align-items: baseline; gap: 10px; }
  .trust-grid { grid-template-columns: minmax(0, 1fr); }
  .benefit-grid { grid-template-columns: minmax(0, 1fr); gap: 10px; }
  .benefit { flex-direction: row; flex-wrap: wrap; align-items: center; column-gap: 14px; padding: 18px; }
  .benefit .ic { margin-bottom: 0; }
  .benefit p { flex-basis: 100%; }
  .tabs { margin-inline: calc(-1 * var(--gutter)); padding-inline: var(--gutter); margin-bottom: 24px; }
  .tab { padding: 0 14px; font-size: 15px; }
  .spec-card { padding: 20px; }
  .toc-title { font-size: 15px; }
  .sticky-bar .btn { padding: 0 18px; }
  /* online */
  .quiz { padding: 14px; }
  .quiz-q { font-size: 16px; }
  .quiz-opt { font-size: 13px; height: 44px; }
  .quiz-feedback { font-size: 13px; }
  .segmented { width: 100%; }
  .seg { flex: 1; padding: 0 8px; }
  .plan { padding: 24px 20px; }
  .topic-grid { grid-template-columns: minmax(0, 1fr); gap: 10px; }
  .topic { padding: 14px 16px; }
  .topic-ic { width: 48px; height: 48px; }
  .dash-showcase { margin-inline: calc(-1 * var(--gutter) + 8px); }
  .callouts li { padding: 16px; }
  /* cart */
  .cart-head { flex-direction: column; align-items: flex-start; gap: 12px; }
  .progress-steps { font-size: 12px; gap: 6px; }
  .progress-steps li + li::before { width: 14px; }
  .progress-steps li:not(.is-current) { font-size: 0; gap: 0; }
  .progress-steps li:not(.is-current) span { font-size: 12px; }
  .cart-item { grid-template-columns: 80px minmax(0, 1fr) auto; grid-template-areas: "thumb info info" "thumb qty total" "thumb remove remove"; gap: 12px 14px; padding: 18px 0; }
  .cart-qty { align-items: flex-start; }
  .cart-line-total { align-self: center; }
  .cart-remove { justify-self: start; min-height: 44px; }
  .cart-title { font-size: 16px; }
  .cross-sell { padding: 16px; }
  .cross-list { grid-template-columns: minmax(0, 1fr); }
  .cross-item .btn { height: 44px; }
  .summary { padding: 20px; }
  .summary > .btn-primary { display: none; }
  .summary .pay-list { justify-content: flex-start; }
  /* checkout */
  .checkout { padding-top: 24px; }
  .checkout-head { flex-direction: column; align-items: flex-start; gap: 12px; margin-bottom: 20px; }
  .co-section { padding: 20px 16px; }
  .co-legend { font-size: 18px; margin-bottom: 16px; }
  .field-grid, .field-grid-address { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px 12px; }
  .field-grid > .field { grid-column: 1 / -1; }
  .field-grid-address > .field { grid-column: span 1; }
  .field-grid-address > .field-wide { grid-column: 1 / -1; }
  .field-grid-address > .field:nth-child(3) { grid-column: 1 / -1; }
  .radio-card { padding: 14px; gap: 12px; }
  .pay-mark { display: none; }
  .confirm .btn-row { width: 100%; }
  /* over ons & faq */
  .quote-card { padding: 28px 24px; }
  .quote-card blockquote { font-size: 22px; }
  .principle-grid, .expect-list { grid-template-columns: minmax(0, 1fr); }
  .notice { flex-direction: column; padding: 24px 20px; }
  .combo-card { padding: 22px; }
  .contact-card { padding: 20px 16px; }
  .contact-form .btn { width: 100%; }
  .search-lg .input { height: 52px; font-size: 16px; }
}

@container site (max-width: 380px) {
  .logo-name { font-size: 15.5px; }
  .logo-mark { width: 30px; height: 30px; }
  .logo { gap: 8px; }
  .pcard { grid-template-columns: 104px minmax(0, 1fr); }
}
